#include <Aevrynd/Audio.h>
#include <algorithm>
#include <array>
#include <cmath>
#include <chrono>
#include <iostream>
#include <thread>

using namespace Aevrynd;

int main(){
    constexpr std::array<uint8_t,52> wave={'R','I','F','F',44,0,0,0,'W','A','V','E','f','m','t',' ',16,0,0,0,1,0,1,0,0x40,0x1f,0,0,0x80,0x3e,0,0,2,0,16,0,'d','a','t','a',8,0,0,0,0,0,0xff,0x7f,0,0,1,0x80};
    AudioLoadResult loaded=LoadWave(wave);if(!loaded||loaded.clip.sampleRate!=8000||loaded.clip.channels!=1||loaded.clip.bitsPerSample!=16||loaded.clip.FrameCount()!=4||std::abs(loaded.clip.DurationSeconds()-.0005f)>.00001f){std::cerr<<"PCM WAVE parsing failed\n";return 1;}
    std::array<uint8_t,52> invalid=wave;invalid[20]=3;if(LoadWave(invalid)){std::cerr<<"Unsupported WAVE format was accepted\n";return 2;}invalid=wave;invalid[40]=9;if(LoadWave(invalid)){std::cerr<<"Misaligned WAVE data was accepted\n";return 3;}
    AudioClip tone=GenerateTone(440,.05f,.25f,48000);if(!tone.Valid()||tone.FrameCount()!=2400||tone.DurationSeconds()<.049f||tone.DurationSeconds()>.051f||std::all_of(tone.samples.begin(),tone.samples.end(),[](uint8_t sample){return sample==0;})){std::cerr<<"Procedural tone generation failed\n";return 4;}
    const AudioPlayback spatial2D=CalculateSpatialAudio(AudioSpatial2D{{}, {400,0},800,1,1,1}),spatial3D=CalculateSpatialAudio(AudioSpatial3D{{}, {1,0,0}, {-10,0,0},20,1,1,1});if(std::abs(spatial2D.volume-.5f)>.001f||std::abs(spatial2D.pan-.5f)>.001f||std::abs(spatial3D.volume-.5f)>.001f||spatial3D.pan!=-1.f){std::cerr<<"Spatial audio calculation failed\n";return 13;}AudioEngine audio;SoundHandle sound=audio.CreateSound(std::move(tone));AudioStats stats=audio.GetStats();if(!sound||stats.residentSounds!=1||stats.residentBytes!=4800){std::cerr<<"Audio resource creation failed\n";return 5;}audio.SetMasterVolume(2);if(audio.GetStats().masterVolume!=1){std::cerr<<"Master volume clamping failed\n";return 6;}const bool available=audio.Initialize(),played=audio.PlaySpatial(sound,AudioSpatial2D{{}, {400,0},800,1,1,1});stats=audio.GetStats();if(played!=available||stats.playRequests!=1||stats.spatialPlayRequests!=1||std::abs(stats.lastSpatialPan-.5f)>.001f||std::abs(stats.lastSpatialGain-.5f)>.001f||stats.successfulPlays!=uint64_t(available)||stats.droppedPlays!=uint64_t(!available)||stats.activeVoices!=std::size_t(available)||available==bool(stats.initializationError)){std::cerr<<"Audio playback telemetry failed\n";return 7;}std::this_thread::sleep_for(std::chrono::milliseconds(120));audio.Update();stats=audio.GetStats();if(stats.activeVoices){std::cerr<<"Completed audio voice was not reclaimed\n";return 8;}const bool looped=audio.Play(sound,{.2f,1,true});if(looped!=available){std::cerr<<"Looped audio playback failed\n";return 9;}audio.StopAll();if(available){for(std::size_t index=0;index<AudioEngine::MaximumVoices;++index)if(!audio.Play(sound,{0,1,true})){std::cerr<<"Audio voice capacity was not available\n";return 10;}if(audio.Play(sound,{0,1,true})||audio.GetStats().activeVoices!=AudioEngine::MaximumVoices){std::cerr<<"Audio voice limit failed\n";return 11;}}audio.StopAll();audio.DestroySound(sound);stats=audio.GetStats();if(stats.activeVoices||stats.residentSounds||stats.residentBytes){std::cerr<<"Audio resource cleanup failed\n";return 12;}std::cout<<"deviceAvailable="<<available<<" initializationError="<<stats.initializationError<<" playRequests="<<stats.playRequests<<" spatialRequests="<<stats.spatialPlayRequests<<" successfulPlays="<<stats.successfulPlays<<" droppedPlays="<<stats.droppedPlays<<'\n';audio.Shutdown();return 0;
}
